import { lazy, Suspense } from 'react';

import { Routes, Route } from 'react-router-dom';

import { Spin } from 'antd';

const Login = lazy(() => import('./pages/auth/Login'));

const Register = lazy(() => import('./pages/auth/Register'));

const RegisterComplete = lazy(() => import('./pages/auth/RegisterComplete'));

const Home = lazy(() => import('./pages/Home'));

const Header = lazy(() => import('./components/nav/Header'));

const ForgotPassword = lazy(() => import('./pages/auth/ForgotPassword'));

const History = lazy(() => import('./pages/user/History'));

const Password = lazy(() => import('./pages/user/Password'));

const AdminPassword = lazy(() => import('./pages/admin/Password'));

const Wishlist = lazy(() => import('./pages/user/Wishlist'));

const AdminDashboard = lazy(() => import('./pages/admin/AdminDashboard'));

const CategoryCreate = lazy(() =>
  import('./pages/admin/category/CategoryCreate')
);

const CategoryUpdate = lazy(() =>
  import('./pages/admin/category/CategoryUpdate')
);

const SubCategoryCreate = lazy(() =>
  import('./pages/admin/subcategory/SubCategoryCreate')
);

const SubCategoryUpdate = lazy(() =>
  import('./pages/admin/subcategory/SubCategoryUpdate')
);

const ProductCreate = lazy(() => import('./pages/admin/product/ProductCreate'));

const ProductUpdate = lazy(() => import('./pages/admin/product/ProductUpdate'));

const AllProducts = lazy(() => import('./pages/admin/product/AllProducts'));

const Coupon = lazy(() => import('./pages/admin/Coupon'));

const Product = lazy(() => import('./pages/Product'));

const CategoryHome = lazy(() => import('./pages/CategoryHome'));

const SubcategoryHome = lazy(() => import('./pages/SubcategoryHome'));

const Shop = lazy(() => import('./pages/Shop'));

const Cart = lazy(() => import('./pages/Cart'));

const Checkout = lazy(() => import('./pages/Checkout'));

const Payment = lazy(() => import('./pages/Payment'));

const UserRoute = lazy(() => import('./components/routes/UserRoute'));

const AdminRoute = lazy(() => import('./components/routes/AdminRoute'));

const SideCartDrawer = lazy(() => import('./components/drawer/SideCartDrawer'));

const App = () => {
  return (
    <>
      <Suspense
        fallback={
          <div className="spiner">
            <Spin size="large" />
          </div>
        }
      >
        <Header />

        <SideCartDrawer />

        <Routes>
          <Route path="/" element={<Home />} />

          <Route path="/login" element={<Login />} />

          <Route path="/register" element={<Register />} />

          <Route path="/register-complete" element={<RegisterComplete />} />

          <Route path="/forgot-password" element={<ForgotPassword />} />

          <Route path="/product/:slug" element={<Product />} />

          <Route path="/category/:slug" element={<CategoryHome />} />

          <Route path="/subcategory/:slug" element={<SubcategoryHome />} />

          <Route path="/shop" element={<Shop />} />

          <Route path="/cart" element={<Cart />} />

          <UserRoute path="/user/history" element={<History />} />

          <UserRoute path="/user/password" element={<Password />} />

          <UserRoute path="/user/wishlist" element={<Wishlist />} />

          <UserRoute path="/checkout" element={<Checkout />} />

          <UserRoute path="/payment" element={<Payment />} />

          <AdminRoute path="/admin/dashboard" element={<AdminDashboard />} />

          <AdminRoute path="/admin/category" element={<CategoryCreate />} />

          <AdminRoute path="/admin/coupon" element={<Coupon />} />

          <AdminRoute path="/admin/password" element={<AdminPassword />} />

          <AdminRoute
            path="/admin/category/:slug"
            element={<CategoryUpdate />}
          />

          <AdminRoute
            path="/admin/subcategory"
            element={<SubCategoryCreate />}
          />

          <AdminRoute
            path="/admin/subcategory/:slug"
            element={<SubCategoryUpdate />}
          />

          <AdminRoute path="/admin/product" element={<ProductCreate />} />

          <AdminRoute path="/admin/allproducts" element={<AllProducts />} />

          <AdminRoute
            path="/admin/allproducts/:slug"
            element={<ProductUpdate />}
          />
        </Routes>
      </Suspense>
    </>
  );
};

export default App;
